    var ct = c.doFinal(utf8(plain));
    var mac = Packages.javax.crypto.Mac.getInstance('HmacSHA256');
    mac.init(new Packages.javax.crypto.spec.SecretKeySpec(bk, 'HmacSHA256'));
    mac.update(concat(iv, ct));
    return b64e(concatAll([iv, ct, mac.doFinal()]));
  }
  function backupDecrypt(v) {
    var bk = backupKey();
    var all = b64d(v);
    if (all.length < 48) throw new Error('备份响应过短');
    var iv = slice(all, 0, 16);
    var sig = slice(all, all.length - 32, all.length);
    var ct = slice(all, 16, all.length - 32);
    var mac = Packages.javax.crypto.Mac.getInstance('HmacSHA256');
    mac.init(new Packages.javax.crypto.spec.SecretKeySpec(bk, 'HmacSHA256'));
    mac.update(concat(iv, ct));
    if (!Packages.java.util.Arrays.equals(mac.doFinal(), sig)) throw new Error('备份响应 HMAC 校验失败');
    var c = Packages.javax.crypto.Cipher.getInstance('AES/CBC/PKCS5Padding');
    c.init(Packages.javax.crypto.Cipher.DECRYPT_MODE,
      new Packages.javax.crypto.spec.SecretKeySpec(bk, 'AES'),
      new Packages.javax.crypto.spec.IvParameterSpec(iv));
    return fromUtf8(c.doFinal(ct));
  }
  function backupPost(url, jsonBody) {
    var opt = {
      method: 'POST', body: text(jsonBody),
      headers: {
        'Content-Type': 'application/json', 'Accept': 'application/json, text/plain, */*',
        'User-Agent': 'okhttp/4.12.0'
      },
      connectTimeout: 15000, readTimeout: 15000
    };
    return text(jx().ajax(url + ',' + JSON.stringify(opt))).trim();
  }
  function getBackupDomains(did) {
    var p = {
      action: 'domains', timestamp: nowSec(), platform: 'android',
      app_version: CFG.appVersion, device_id: did,
      client_info: { network: 'wifi', system_version: 'Android 11' }
    };
    var resp = backupPost(BACKUP_URL, JSON.stringify({ data: backupEncrypt(JSON.stringify(p)) }));
    var r = JSON.parse(resp);
    var d = JSON.parse(backupDecrypt(r.data));
    var domains = (d.data && d.data.backup_domains) || [];
    var out = [];
    for (var i = 0; i < domains.length; i++) {
      if (domains[i].enabled && domains[i].base_url) {
        var burl = text(domains[i].base_url);
        while (burl.charAt(burl.length - 1) === '/') burl = burl.slice(0, -1);
        out.push(burl + '/');
      }
    }
    return out;
  }
  function decryptResponse(raw, key) {
    var s = text(raw).trim();
    if (s.charAt(0) === '{') return JSON.parse(s);
    return JSON.parse(aesDecrypt(JSON.parse(decodeBody(s)), key));
  }
  function handshake(force) {
    var saved = cget('xy_aes_key');
    if (!force && saved) return b64d(saved);
    var preferred = cget('xy_base_url'), bases = CFG.bases.slice(0);
    if (preferred) { bases = bases.filter(function (x) { return x !== preferred; }); bases.unshift(preferred); }
    try {
      var bd = getBackupDomains(deviceId());
      for (var bi = bd.length - 1; bi >= 0; bi--) { if (bases.indexOf(bd[bi]) < 0) bases.unshift(bd[bi]); }
    } catch (e) {}
    var errors = [];
    for (var i = 0; i < bases.length; i++) {
      try {
        var key = randomBytes(32), ts = nowSec(), d = deviceId(), ek = rsa(key);
        var sigHash = digest('SHA-256', d + '|' + ts + '|' + ek);
        var req = {
          d: d, k: ek, t: ts, s: rsa(utf8(sigHash)), merchant_id: CFG.merchantId,
          site_id: CFG.siteId, platform: 'android', device_name: 'Legado', app_version: CFG.appVersion, is_rooted: false
        };
        var result = decryptResponse(ajaxPost(join(bases[i], CFG.handshake), encodeBody(JSON.stringify(req))), key);
        if (Number(result.code) !== 0) throw new Error(result.message || ('code=' + result.code));
        cput('xy_base_url', bases[i]); cput('xy_aes_key', b64e(key));
        return key;
      } catch (e) { errors.push(bases[i] + ' ' + text(e.message || e)); }
    }
    throw new Error('星愿瓶所有线路握手失败：' + errors.join('；'));
  }
  function requestBody(data, key) {
    var ts = nowSec(), nonce = randomHex(16), d = deviceId();
    var enc = aesEncrypt(JSON.stringify(data), key, ts + '|' + nonce + '|' + d);
    return encodeBody(JSON.stringify({ d: d, t: ts, n: nonce, iv: b64e(enc.iv), c: b64e(enc.cipher), tag: b64e(enc.tag) }));
  }
  function securePost(path, data, retried) {
    try {
      var key = handshake(false), base = cget('xy_base_url') || CFG.bases[0];
      return decryptResponse(ajaxPost(join(base, path), requestBody(data, key)), key);
    } catch (e) {
      if (retried) throw e;
      cput('xy_aes_key', '');
      handshake(true);
      return securePost(path, data, true);
    }
  }
  function common(extra) {
    var out = { token: cget('xy_token'), merchant_id: CFG.merchantId, site_id: CFG.siteId };
    extra = extra || {};
    for (var k in extra) out[k] = extra[k];
    return out;
  }
  function ok(r, label) {
    if (!r || Number(r.code) !== 0) throw new Error(label + '：' + text(r && r.message || '接口返回失败'));
    return r.data || {};
  }
  function token() { return cget('xy_token'); }
  function login(user, pass) {
    if (!text(user).trim() || !text(pass)) throw new Error('请输入账号和密码');
    var r = securePost('api/app/an/a/api/login.php', {
      username: text(user).trim(), password: text(pass), device_name: 'Legado', app_version: CFG.appVersion
    });
    var d = ok(r, '登录失败');
    if (!d.token) throw new Error('登录成功但未返回 Token');
    cput('xy_token', d.token); cput('xy_username', text(user).trim());
    return d;
  }
  function searchSource() {
    var s = cget('xy_search_source');
    if (SEARCH[s]) return s;
    try {
      var m = source.getLoginInfoMap() || {};
      s = text(m['搜索来源']);
    } catch (e) {}
    return SEARCH[s] ? s : '超级搜索';
  }
  function saveSearchSource(v) {
    var s = text(v);
    if (!SEARCH[s]) s = '超级搜索';
    cput('xy_search_source', s);
    return s;
  }
  function dataUrl(obj) {
    var base = cget('xy_base_url') || CFG.bases[0];
    return join(base, '__legado_payload__') + '?xy=' + b64url(JSON.stringify(obj));
  }
  function payload(raw) {
    var s = text(raw).trim();
    var match = s.match(/[?&]xy=([^&#]+)/);
    if (match && match[1]) s = fromUtf8(b64d(decodeURIComponent(match[1])));
    else if (/^data:text\/plain;base64,/i.test(s)) s = fromUtf8(b64d(s.replace(/^data:text\/plain;base64,/i, '').split(/[#,]/)[0]));
    return JSON.parse(s || '{}');
  }
  function stripHtml(v) { return text(v).replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').trim(); }
  function pick(o, names, def) {
    o = o || {};
    for (var i = 0; i < names.length; i++) if (o[names[i]] != null && text(o[names[i]]) !== '') return o[names[i]];
    return def == null ? '' : def;
  }
  function resultList(d) {
    if (Array.isArray(d)) return d;
    var names = ['list', 'results', 'books', 'items'];
    for (var i = 0; i < names.length; i++) if (Array.isArray(d && d[names[i]])) return d[names[i]];
    return [];
  }
  function normalizeSearch(item, sourceName) {
    var src = SEARCH[sourceName] || SEARCH['超级搜索'];
    var title = stripHtml(pick(item, ['display_title', 'title', 'book_name', 'book_title', 'article_title', 'name']));
    var author = stripHtml(pick(item, ['author', 'author_name', 'display_info', 'cp_name']));
    var intro = stripHtml(pick(item, ['intro', 'abstract', 'book_intro', 'article_intro', 'content', 'sub_title']));
    var cover = pick(item, ['image_link', 'img_url', 'cover_url', 'cover', 'book_cover', 'article_cover', 'audio_thumb_uri']);
    var kind = stripHtml(pick(item, ['category', 'ptags', 'top_category_name', 'first_category_name', 'book_type_name', 'labels']));
    var p;
    if (src.key === 'paper') p = { kind: 'paper', mark: pick(item, ['mark']), title: title };
    else if (src.key === 'local') p = { kind: 'direct', book_id: pick(item, ['book_id', 'bookId']), article_id: pick(item, ['article_id', 'articleId']) };
    else p = { kind: 'external', source: src.key, book_id: pick(item, ['book_id', 'bookId', 'id']), book_type: pick(item, ['book_type'], 0) };
    return {
      name: title || ('星愿瓶书籍 ' + text(p.book_id || p.mark)), author: author,
      intro: intro, coverUrl: text(cover), kind: kind || sourceName,
      lastChapter: stripHtml(pick(item, ['last_chapter_title', 'state', 'sub_title', 'likeText'])),
      wordCount: text(pick(item, ['word_count', 'word_number', 'score', 'rating_score'])),
      bookUrl: dataUrl(p)
    };
  }
  function search(p) {
    var sourceName = SEARCH[p.source] ? p.source : searchSource(), src = SEARCH[sourceName];
    var page = Math.max(1, Number(p.page || 1)), keyword = text(p.key).trim();
    if (!keyword) return [];
    var d;
    if (src.key === 'paper') {
      d = ok(securePost(src.path, common({ channel_id: 9, content: keyword })), '纸糊搜索失败');
      var paper = resultList(d), start = (page - 1) * 20;
      paper = paper.slice(start, start + 20);
      return paper.map(function (x) { return normalizeSearch(x, sourceName); });
    }
    d = ok(securePost(src.path, common({ keyword: keyword, page: page, page_size: 20 })), sourceName + '搜索失败');
    return resultList(d).map(function (x) { return normalizeSearch(x, sourceName); });
  }
  function rank(p) {
    var cat = p.category === 'long' ? 'long' : 'short';
    var path = cat === 'long' ? 'api/app/an/a/api/get_book_rank_list.php' : 'api/app/an/a/api/get_rank_list.php';
    var d = ok(securePost(path, common({ rank_type: text(p.rank_type || 'all'), page: Math.max(1, Number(p.page || 1)), page_size: 20 })), '排行榜加载失败');
    return resultList(d).map(function (x) {
      var isLong = cat === 'long';
      return {
        name: stripHtml(pick(x, isLong ? ['book_title', 'title'] : ['article_title', 'title'])),
        author: stripHtml(pick(x, ['author_name', 'author'])),
        intro: stripHtml(pick(x, isLong ? ['book_intro', 'intro'] : ['article_intro', 'intro'])),
        coverUrl: text(pick(x, isLong ? ['book_cover', 'cover'] : ['article_cover', 'cover'])),
        kind: (isLong ? '长篇' : '短篇') + ' · 第' + text(pick(x, ['rank_position'], '?')) + '名',
        lastChapter: '热度 ' + text(pick(x, ['rank_score', 'period_votes'], 0)),
        wordCount: text(pick(x, ['rating_score'], '')),
        bookUrl: dataUrl({ kind: 'direct', book_id: pick(x, ['book_id']), article_id: pick(x, ['article_id']) })
      };
    });
  }
  function listFromPayload(raw) {
    var p = payload(raw);
    if (p.kind === 'search') return search(p);
    if (p.kind === 'rank') return rank(p);
    return [];
  }
  function externalUrl(p) {
    var id = encodeURIComponent(text(p.book_id));
    if (p.source === 'jj') return 'https://www.jjwxc.net/onebook.php?novelid=' + id;
    if (p.source === 'qidian') return 'https://www.qidian.com/book/' + id + '/';
    if (p.source === 'fanqie') return 'https://m.toutiao.com/novel/book/page/v1/share/page/?book_id=' + id;
    if (p.source === 'qimao') return Number(p.book_type) === 4
      ? 'https://app-share.wtzw.com/app-h5/freebook/short-story-detail/' + id
      : 'https://app-share.wtzw.com/app-h5/freebook/article-detail/' + id;
    if (p.source === 'shuqi_short') return 'https://t.shuqi.com/shortNovel/reader/' + id;
    if (p.source === 'shuqi_long') return 'http://c10.shuqireader.com/sapi/book/sharecover/?bookId=' + id + '&anyUpTime=1670376345&topClass=502&platform=ios';
    throw new Error('不支持的外部搜索来源：' + p.source);
  }
  function resolveBookId(p) {
    if (p.kind === 'direct' && p.book_id) return text(p.book_id);
    var d;
    if (p.kind === 'paper') d = ok(securePost('api/app/an/a/api/parse_article.php', common({ mark: text(p.mark) })), '纸糊结果解析失败');
    else if (p.kind === 'external') d = ok(securePost('api/app/an/a/api/parse.php', common({ channel_id: 9, content: externalUrl(p) })), '外部书籍解析失败');
    else throw new Error('书籍链接参数无效');
    var id = pick(d, ['book_id', 'bookId']);
    if (!id) throw new Error('解析成功但未返回星愿瓶书籍 ID');
    return text(id);
  }
  function getBook(id) { return ok(securePost('api/app/an/a/api/get_book.php', common({ book_id: Number(id) })), '详情加载失败'); }
  function bookInfo(raw) {
    if (!token()) throw new Error('请先在书源登录页登录星愿瓶');
    var p = payload(raw), id = resolveBookId(p), d = getBook(id);
    var b = d.bookinfo || d.book_info || d.book || d;
    var chapters = resultList({ list: d.chapters || d.chapter_list || [] });
    var last = chapters.length ? chapters[chapters.length - 1] : {};
    var categories = pick(b, ['categories', 'category'], []);
    if (Array.isArray(categories)) categories = categories.map(function (x) { return typeof x === 'object' ? pick(x, ['name', 'category_name', 'title']) : text(x); }).join(', ');
    return {
      name: stripHtml(pick(b, ['book_title', 'book_name', 'title'])),
      author: stripHtml(pick(b, ['author_name', 'author'])),
      coverUrl: text(pick(b, ['book_cover', 'cover', 'cover_url'])),
      intro: stripHtml(pick(b, ['book_abstract', 'abstract', 'intro'])),
      kind: stripHtml(categories),
      lastChapter: stripHtml(pick(last, ['article_title', 'chapter_title', 'title'])),
      wordCount: text(pick(b, ['article_num', 'chapter_count'], chapters.length)) + '章',
      tocUrl: dataUrl({ kind: 'toc', book_id: id })
    };
  }
  function chapters(raw) {
    var p = payload(raw), d = getBook(p.book_id), list = d.chapters || d.chapter_list || [];
    return list.map(function (x, i) {
      var aid = pick(x, ['article_id', 'chapter_id', 'id']);
      return {
        chapterName: stripHtml(pick(x, ['article_title', 'chapter_title', 'title'], '第' + (i + 1) + '章')),
        chapterUrl: dataUrl({ kind: 'chapter', book_id: text(p.book_id), article_id: text(aid) }),
        isVip: false, isPay: false,
        updateTime: text(pick(x, ['update_time', 'updated_at'])),
        wordCount: text(pick(x, ['word_count', 'article_word_count']))
      };
    });
  }
  function content(raw) {
    var p = payload(raw);
    var d = ok(securePost('api/app/an/a/api/get_article.php', common({ book_id: Number(p.book_id), article_id: Number(p.article_id) })), '正文加载失败');
    var body = pick(d, ['article_content', 'content', 'chapter_content']);
    if (!text(body).trim()) {
      var note = pick(d, ['message', 'article_abstract', 'abstract'], '正文为空或账号暂无访问权限');
      throw new Error(text(note));
    }
    return text(body).replace(/\r\n/g, '\n').replace(/\r/g, '\n');
  }
  function getVideoRewardRules() {
    return securePost('api/app/an/a/api/get_video_reward_rules.php', common({}));
  }
  function createVideoAd(syspt) {
    return securePost('api/app/an/a/api/get_video_ad.php', common({ syspt: Number(syspt || 1) }));
  }
  function reportTransId(guanggaoid, transId) {
    var gid = text(guanggaoid).trim(), tid = text(transId).trim();
    if (!gid) throw new Error('广告任务标识不能为空');
    if (!tid) throw new Error('广告 SDK 交易标识不能为空');
    return securePost('api/app/an/a/api/ad_report_transid.php', common({ guanggaoid: gid, transId: tid }));
  }
  function getVideoAdStatus(guanggaoid) {
    var gid = text(guanggaoid).trim();
    if (!gid) throw new Error('广告任务标识不能为空');
    return securePost('api/app/an/a/api/get_video_ad_status.php', common({ guanggaoid: gid }));
  }
  function simulateTransId() {
    return 'sdk_trans_' + randomHex(24);
  }
  function extractAdId(r) {
    if (!r || Number(r.code) !== 0) return '';
    var d = r.data;
    if (typeof d === 'string' || typeof d === 'number') return String(d);
    if (d && typeof d === 'object') return String(d.guanggaoid || d.id || '');
    return '';
  }
  function todayStr() {
    var sdf = new Packages.java.text.SimpleDateFormat('yyyyMMdd');
    return String(sdf.format(new Packages.java.util.Date()));
  }
  function getTodayAdCount() {
    var key = 'xy_ad_count_' + todayStr();
    var localCount = Number(cget(key) || 0);
    var serverCount = 0;
    try {
      var prog = getVideoRewardRules();
      if (prog && Number(prog.code) === 0) serverCount = Number((prog.data || {}).today_watch_count || 0);
    } catch (e) {}
    var count = Math.max(localCount, serverCount);
    if (serverCount > localCount) cput(key, String(serverCount));
    return count;
  }
  function incTodayAdCount() {
    var key = 'xy_ad_count_' + todayStr();
    cput(key, String(Number(cget(key) || 0) + 1));
  }
  function watchAdAuto() {
    var count = getTodayAdCount();
    if (count >= 3) throw new Error('今日已成功刷3次，无法继续');
    var ad = createVideoAd(1);
    if (!ad || Number(ad.code) !== 0) throw new Error('创建广告任务失败：' + text(ad && ad.message || '未知错误'));
    var gid = extractAdId(ad);
    if (!gid) throw new Error('未获取到广告标识');
    var tid = simulateTransId();
    var report = reportTransId(gid, tid);
    if (!report || Number(report.code) !== 0) throw new Error('上报transId失败：' + text(report && report.message || ''));
    var st, sd, lastMsg = '';
    for (var i = 0; i < 15; i++) {
      if (i > 0) Packages.java.lang.Thread.sleep(2000);
      st = getVideoAdStatus(gid);
      sd = (st && st.data) || {};
      lastMsg = text(st && st.message || '');
      if (Number(st && st.code) === 0 && Number(sd.status) >= 1) {
        incTodayAdCount();
        return { success: true, gid: gid, award: text(sd.award_name || sd.award_code || sd.reward_name || '已到账') };
      }
    }
    return { success: false, gid: gid, message: lastMsg || '轮询超时' };
  }
  function watchAdAll(onProgress) {
    var target = 3, done = getTodayAdCount();
    var remaining = Math.max(0, target - done);
    if (remaining === 0) return { total: 0, success: 0, results: [], alreadyDone: done, message: '今日已成功刷3次，无需再刷' };
    var results = [];
    var success = 0;
    for (var i = 0; i < remaining; i++) {
      if (onProgress) { try { onProgress(i + 1, remaining, success, done); } catch (e) {} }
      try {
        var r = watchAdAuto();
        results.push(r);
        if (r.success) {
          success++;
          if (done + success >= 3) break;
        }
        else { break; }
      } catch (e) {
        results.push({ success: false, message: text(e.message || e) });
        break;
      }
      if (i < remaining - 1) Packages.java.lang.Thread.sleep(2000);
    }
    return { total: remaining, success: success, results: results, alreadyDone: done };
  }
  return {
    setEnv: setEnv, config: CFG, searchNames: Object.keys(SEARCH), token: token, login: login,
    searchSource: searchSource, saveSearchSource: saveSearchSource,
    dataUrl: dataUrl, listFromPayload: listFromPayload, bookInfo: bookInfo,
    chapters: chapters, content: content, handshake: handshake, securePost: securePost,
    getVideoRewardRules: getVideoRewardRules, createVideoAd: createVideoAd,
    reportTransId: reportTransId, getVideoAdStatus: getVideoAdStatus,
    simulateTransId: simulateTransId, watchAdAuto: watchAdAuto, watchAdAll: watchAdAll,
    getTodayAdCount: getTodayAdCount
  };
})();

